  456	static void *velawear_watchdog_thread(void *context)
  457	{
  458	  velawear_agent_t *agent = (velawear_agent_t *)context;
  459	  bool reported_stall = false;
  460	
  461	  syslog(LOG_INFO, "[Watchdog] Software monitor started\n");
  462	  while (agent->running)
