  469	                 "[Watchdog] Main loop heartbeat stalled (%lu ms)\n",
  470	                 (unsigned long)age);
  471	          reported_stall = true;
  472	        }
  473	      else if (age <= 5000)
  474	        {
  475	          reported_stall = false;
