  522	        }
  523	      return VELAWEAR_OK;
  524	    }
  525	
  526	  if (ioctl(agent->watchdog_fd, WDIOC_SETTIMEOUT, timeout_ms) < 0 ||
  527	      ioctl(agent->watchdog_fd, WDIOC_START, 0) < 0)
  528	    {
  529	      syslog(LOG_WARNING, "[Watchdog] Hardware watchdog start failed: %d\n",
  530	             errno);
  531	      close(agent->watchdog_fd);
  532	      agent->watchdog_fd = -1;
