  537	        }
  538	      return VELAWEAR_OK;
  539	    }
  540	
  541	  agent->watchdog_active = true;
  542	  ret = velawear_watchdog_start_software(agent);
  543	  if (ret != VELAWEAR_OK)
  544	    {
  545	      ioctl(agent->watchdog_fd, WDIOC_STOP, 0);
  546	      close(agent->watchdog_fd);
  547	      agent->watchdog_fd = -1;
  548	      agent->watchdog_active = false;
  549	      return VELAWEAR_OK;
  550	    }
  551	
  552	  syslog(LOG_INFO, "[Watchdog] Hardware watchdog started (%d ms)\n",
  553	         timeout_ms);
