  848	static int velawear_start(velawear_agent_t *agent)
  849	{
  850	  int ret;
  851	
  852	  /* The main loop owns event queue consumption.  Do not start a second
  853	   * consumer thread for the same mqueue. */
  854	
  855	  /* Start action manager thread. */
  856	
  857	  ret = action_manager_start(&agent->actions);
  858	  if (ret < 0)
  859	    {
  860	      syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
  861	      return ret;
  862	    }
  863	
  864	  /* Decision rules are evaluated synchronously for each event. */
  865	
  866	  /* Mark agent as running before starting the sensor producer. */
  867	
  868	  agent->running = true;
  869	  ret = velawear_watchdog_start(agent);
  870	  if (ret < 0)
  871	    {
  872	      agent->running = false;
  873	      return ret;
  874	    }
  875	
  876	  if (agent->imu.initialized)
  877	    {
  878	      ret = pthread_create(&agent->imu_thread, NULL,
  879	                           velawear_imu_thread, agent);
  880	      if (ret != 0)
  881	        {
  882	          agent->running = false;
  883	          syslog(LOG_ERR, "[VelaWear] IMU thread start failed: %d\n", ret);
  884	          return VELAWEAR_ERR_IO;
  885	        }
  886	      agent->imu_thread_started = true;
  887	    }
  888	
  889	  return VELAWEAR_OK;
  890	}
